import * as React from "react";

export interface TextCursorFollowProps {
  text?: string;
  className?: string;
  delayMs?: number;
}

/**
 * Text Cursor Follow
 * Character-by-character reveal with spring-loaded entrance per glyph.
 */
export function TextCursorFollow({
  text = "Text Cursor Follow",
  className = "",
  delayMs = 50,
}: TextCursorFollowProps): React.JSX.Element {
  const [chars, setChars] = React.useState(0);
  const [loop, setLoop] = React.useState(0);

  React.useEffect(() => {
    let i = 0;
    const id = setInterval(() => {
      i++;
      setChars(i);
      if (i >= text.length) {
        clearInterval(id);
        setTimeout(() => { setChars(0); setLoop(l => l + 1); }, 2000);
      }
    }, delayMs);
    return () => clearInterval(id);
  }, [text, delayMs, loop]);

  return (
    <div className={`select-none font-display font-bold ${className}`}>
      <span className="text-3xl text-ink tracking-tight">
        {text.split("").map((c, i) => (
          <span
            key={i}
            style={{
              display: "inline-block",
              opacity: i < chars ? 1 : 0,
              transform: i < chars ? "translateY(0) scale(1)" : "translateY(12px) scale(0.8)",
              transition: `opacity 0.25s ${i * 0.02}s, transform 0.3s cubic-bezier(0.34,1.56,0.64,1) ${i * 0.02}s`,
            }}
          >
            {c === " " ? " " : c}
          </span>
        ))}
      </span>
      <span className="inline-block w-0.5 h-7 bg-oxide align-middle ml-1 animate-pulse" />
    </div>
  );
}

import * as React from "react";
import { TextCursorFollow } from "./text-cursor-follow";

export default function TextCursorFollowDemo(): React.JSX.Element {
  return (
    <div className="flex min-h-[360px] w-full items-center justify-center rounded-2xl bg-neutral-950 p-8 border border-neutral-800">
      <TextCursorFollow
        text="Next Generation Web Interfaces"
        className="text-3xl sm:text-5xl font-mono font-bold tracking-tight text-white text-center"
      />
    </div>
  );
}
